    [3761]={name="Deadskull Shield",quality=2,ilvl=32,sourceType="quest_reward",instructions="Reward from the quest 'Battle of Hillsbrad' - pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Battle of Hillsbrad",lore="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."},
    [3765]={name="Brigand's Pauldrons",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Taretha's Gift' - pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Taretha's Gift",lore="The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."},
