    [4430]={name="Ethereal Talisman",quality=2,ilvl=43,sourceType="quest_reward",instructions="Reward from the quest 'The Crown of Will'. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="The Crown of Will",lore="All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."},
    [4443]={name="Grim Pauldrons",quality=2,ilvl=36,sourceType="quest_reward",instructions="Reward from the quest 'To Steal From Thieves' - pick it over the other choices. In Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
    [4477]={name="Nefarious Buckler",quality=2,ilvl=34,reqLevel=29,sourceType="world_drop",instructions="Drops from Nefaru (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Nefaru"},
