    [4745]={name="War Rider Bracers",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Wanted!  Otto and Falconcrest' - pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Wanted!  Otto and Falconcrest",lore="The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto. Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."},
