    [5328]={name="Cinched Belt",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Disruption Ends' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5343]={name="Barkeeper's Cloak",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Raptor Horns'. In The Barrens.",zone="The Barrens",questName="Raptor Horns",lore="The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'. In The Barrens.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5404]={name="Serpent's Shoulders",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Lady Anacondra in Wailing Caverns.",zone="Wailing Caverns",npc="Lady Anacondra"},
