    [6187]={name="Dwarven Defender",quality=2,ilvl=17,sourceType="quest_reward",instructions="Reward from the quest 'In Defense of the King's Lands' - pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="In Defense of the King's Lands",lore="our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."},
    [6189]={name="Durable Chain Shoulders",quality=1,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Chok'sul' - pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
    [6195]={name="Wax-polished Armor",quality=2,ilvl=15,reqLevel=10,sourceType="world_drop",instructions="Drops from Grizlak (rare spawn).",npc="Grizlak"},
