    [9637]={name="Shinkicker Boots",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Deliver to MacKinley' - pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Deliver to MacKinley",lore="Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."},
    [9664]={name="Sentinel's Guard",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Delivering the Relic' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Delivering the Relic",lore="If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."},
    [9686]={name="Spirit of the Faerie Dragon",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Weapons of Spirit' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Weapons of Spirit",lore="Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."},
