    [10358]={name="Duracin Bracers",quality=2,ilvl=36,sourceType="quest_reward",instructions="Reward from the quest 'Power Stones' - pick it over the other choices. In Uldaman.",zone="Uldaman",questName="Power Stones",lore="A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."},
