    [10659]={name="Shard of the Splithooves",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Heroes of Old'. In Blasted Lands.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
    [10686]={name="Aegis of Battle",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Venom to the Undercity' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Venom to the Undercity",lore="The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."},
    [10740]={name="Centurion Legplates",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Rise, Obsidion!' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="Rise, Obsidion!",lore="It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."},
