    [15411]={name="Mark of Fordring",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'In Dreams' - pick it over the other choices. In Western Plaguelands.",zone="Western Plaguelands",questName="In Dreams",lore="For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"},
