    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280.  Effect lasts for 20 sec. (2 Min Cooldown)"},
    [21201]={name="Signet Ring of the Bronze Dragonflight",quality=4,ilvl=60,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Path of the Conqueror'. In Tanaris.",zone="Tanaris",questName="The Path of the Conqueror"},
    [21206]={name="Signet Ring of the Bronze Dragonflight",quality=4,ilvl=60,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Path of the Invoker'. In Tanaris.",zone="Tanaris",questName="The Path of the Invoker"},
    [21269]={name="Blessed Qiraji Bulwark",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21316]={name="Leggings of the Ursa",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Deadwood of the North' - pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21387]={name="Avenger's Crown",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Crown'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Avenger's Crown",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21388]={name="Avenger's Greaves",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Greaves'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Avenger's Greaves",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21389]={name="Avenger's Breastplate",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Breastplate'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Avenger's Breastplate",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21390]={name="Avenger's Legguards",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Legguards'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Avenger's Legguards",lore="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."},
    [21391]={name="Avenger's Pauldrons",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Pauldrons'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Avenger's Pauldrons",lore="Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"},
    [21395]={name="Blade of Eternal Justice",quality=4,ilvl=70,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Blade of Eternal Justice'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Blade of Eternal Justice",lore="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong."},
    [21397]={name="Cape of Eternal Justice",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cape of Eternal Justice'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Cape of Eternal Justice",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
    [21485]={name="Buru's Skull Fragment",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Buru the Gorger in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Buru the Gorger"},
    [21507]={name="Amulet of the Shifting Sands",quality=4,ilvl=70,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Ossirian' - pick it over the other choices. In Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",questName="The Fall of Ossirian",lore="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."},
