    [22691]={name="Corrupted Ashbringer",quality=4,ilvl=86,reqLevel=60,sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease",lore="The Ashbringer after Renault Mograine used it on his own father. It weeps in the Scarlet Monastery, and the undead of Naxxramas recoil from anyone carrying it.",proc="Chance on hit: Steals 185 to 215 life from target enemy."},
    [22699]={name="Icebane Leggings",quality=4,ilvl=80,sourceType="quest_reward",instructions="Reward from the quest 'The Only Song I Know...' - pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Only Song I Know...",lore="You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"},
    [22732]={name="Mark of C'Thun",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22939]={name="Band of Unanswered Prayers",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22940]={name="Icebane Pauldrons",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina in Naxxramas.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22954]={name="Kiss of the Spider",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna in Naxxramas.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [22981]={name="Gluth's Missing Collar",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gluth in Naxxramas.",zone="Naxxramas",npc="Gluth",lore="A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."},
